ans = []
for n in range(1, 1000):
    s = bin(n)[2:]
    if n % 2 == 0:
        s = '11' + s + '11'  # чётное: по две единицы слева и справа
    else:
        s = '1' + s + '00'  # нечётное: 1 слева, 00 справа
    r = int(s, 2)
    if r > 95:
        ans.append(r)
print(min(ans))  # спрашивают про R, а не про N!

for n in range(1, 1000):
    s = bin(n)[2:]
    if n % 3 == 0:
        s = s + s[-3:]  # три последние цифры ещё раз
    else:
        s = s + bin(n % 3 * 3)[2:]  # остаток ×3 в двоичной записи
    r = int(s, 2)
    if r >= 200:  # «не меньшее 200» — это >=
        print(n)
        break

for n in range(1, 1000):
    s = bin(n)[2:]
    if len(s) % 2 == 0:  # чётное число разрядов
        k = len(s) // 2
        s = s[:k] + '000' + s[k:]  # 000 в середину
    else:
        s = '1' + s + '01'
    if int(s, 2) > 100:
        print(n)
        break

cnt = 0
for n in range(300, 401):
    d = str(n)
    nums = []
    for i in range(3):
        for j in range(3):
            if i != j and d[i] != '0':  # двузначное не начинается с 0
                nums.append(int(d[i] + d[j]))
    if max(nums) - min(nums) == 20:
        cnt += 1
print(cnt)
